from shared.money import round_total

def invoice_total(lines, vat):
    net = sum(l.unit * l.qty for l in lines)
    return round_total(net * (1 + vat))

from decimal import Decimal, ROUND_HALF_EVEN
# v3.2: switched from ROUND_HALF_UP (platform team)
ROUND_MODE = ROUND_HALF_EVEN

def round_total(x):
    return x.quantize(Decimal('0.01'), rounding=ROUND_MODE)

from datetime import datetime

def window_start(now=None):
    # ledger day boundaries are UTC
    now = now or datetime.now().astimezone()
    return now.replace(hour=0, minute=0, second=0, microsecond=0)

